WITH flagged AS (SELECT *, CASE WHEN LAG(reading_ts) OVER (PARTITION BY device_code ORDER BY reading_ts, id) IS NULL OR reading_ts > LAG(reading_ts) OVER (PARTITION BY device_code ORDER BY reading_ts, id) + INTERVAL '1' HOUR THEN 1 ELSE 0 END AS new_group_flag FROM device_readings), sessionized AS (SELECT *, SUM(new_group_flag) OVER (PARTITION BY device_code ORDER BY reading_ts, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS island_id FROM flagged) SELECT DATE_TRUNC('HOUR', reading_ts) AS hour_window, AVG(new_group_flag) AS avg_new_group_flag, COUNT(*) FILTER (WHERE device_code = 'DV-04') AS dv_04_rows, SORT_ARRAY(COLLECT_SET(device_code)) AS device_code_list, COUNT(CASE WHEN device_code = 'DV-02' THEN 1 END) AS dv_02_count FROM sessionized GROUP BY DATE_TRUNC('HOUR', reading_ts) ORDER BY dv_04_rows DESC NULLS FIRST
